module.exports = function(RED) {
    const sessionManager = require("../../runtime/session-manager").getInstance(RED);

    function EndCallNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;

        node.on('input', async function(msg) {
            const sessionId = msg.sessionId;
            if (sessionId) {
                await sessionManager.markCompleted(sessionId);
            }
            node.status({ fill: "grey", shape: "dot", text: "Call Ended" });
            // In full impl: send Hangup action to Africa's Talking
        });
    }
    RED.nodes.registerType("end-call", EndCallNode);
};